{
  "certificate": {
    "number": "R76/1992-DE1-07.07",
    "scheme": "A",
    "page_total": 2,
    "member_state": "Germany",
    "date_issued": "2011-05-02"
  },
  "issuing_authority": {
    "name": "Physikalisch-Technische Bundesanstalt",
    "address_lines": ["Bundesallee 100", "38116 Braunschweig"],
    "person_responsible": "Dr. Dirk Ratschko",
    "person_title": "Head of Department"
  },
  "applicants": [
    {
      "name": "Schenck Process GmbH",
      "address_lines": ["Pallaswiesenstr. 100", "64293 Darmstadt", "Germany"]
    }
  ],
  "manufacturers": [
    {
      "name": "Schenck Process GmbH",
      "address_lines": ["Pallaswiesenstr. 100", "64293 Darmstadt", "Germany"]
    }
  ],
  "certified_type": {
    "category": "Non-automatic weighing instrument",
    "type_designations": ["DISOMAT Tersus"],
    "module_designation": "Not applicable",
    "description": "Non-automatic electromechanical weighing instrument with or without lever system, further characteristics see page 2. Designed as weighbridge, road vehicle scale, rail-weighbridge, hopper scale, crane scale, overhead scale track as well as mobile instrument in conveyor systems. The weighing instrument is equipped with a lever system or directly introduces the force into one or more load cells. The weighing ranges comprising Max, verification scale intervals, number of verification scale intervals and scale intervals may be selected considering the limiting values in table 1."
  },
  "characteristics": {
    "type_level": {
      "tare_balancing_range": {
        "value": 100,
        "unit_symbol": "%"
      },
      "temperature_range": {
        "value": { "min": -30, "max": 40 },
        "unit_symbol": "°C",
        "footnote_markers": ["4)"]
      }
    },
    "config_level": [
      {
        "attribute": "maximum_capacity",
        "axis": "accuracy_class",
        "values": [
          { "condition": "(III)", "value": { "min": 2, "max": 600000 }, "unit_symbol": "kg" },
          { "condition": "(IIII)", "value": { "min": 2, "max": 600000 }, "unit_symbol": "kg" }
        ]
      },
      {
        "attribute": "max_verification_scale_intervals_n",
        "axis": "accuracy_class",
        "values": [
          { "condition": "(III)", "value": 8000, "unit_symbol": null, "footnote_markers": ["1)"] },
          { "condition": "(IIII)", "value": 1000, "unit_symbol": null, "footnote_markers": ["1)"] }
        ]
      },
      {
        "attribute": "partial_range_max_scale_intervals_ni",
        "axis": "accuracy_class",
        "values": [
          { "condition": "(III)", "value": 4000, "unit_symbol": null, "footnote_markers": ["2)"] },
          { "condition": "(IIII)", "value": 1000, "unit_symbol": null, "footnote_markers": ["2)"] }
        ]
      },
      {
        "attribute": "ratio_max_over_e1",
        "axis": "accuracy_class",
        "values": [
          { "condition": "(III)", "value": 15000, "unit_symbol": null, "footnote_markers": ["2)", "3)"] },
          { "condition": "(IIII)", "value": 5000, "unit_symbol": null, "footnote_markers": ["2)", "3)"] }
        ]
      },
      {
        "attribute": "preset_tare_range",
        "axis": "instrument_range_configuration",
        "values": [
          { "condition": "each range of single- and multiple range instruments", "value": 100, "unit_symbol": "%", "footnote_markers": ["1)"] },
          { "condition": "multi-interval instruments (of Max1)", "value": 100, "unit_symbol": "%", "footnote_markers": ["2)"] }
        ]
      }
    ]
  },
  "matrix_tables": [
    {
      "name": "Table 1 – Limiting values for the selection of weighing ranges",
      "columns": ["accuracy_class", "max", "n_max", "partial_range_ni_max", "max_e1_ratio_max", "tare_balancing_range", "preset_tare_range", "temperature_range"],
      "column_units": [null, null, null, null, null, "%", "%", "°C"],
      "rows": [
        {
          "accuracy_class": "(III)",
          "max": "2 kg ... 600 t",
          "n_max": 8000,
          "partial_range_ni_max": 4000,
          "max_e1_ratio_max": 15000,
          "tare_balancing_range": "100 % of Max",
          "preset_tare_range": "100 % of Max (1) / 100 % of Max1 (2)",
          "temperature_range": "-30 °C / +40 °C (4)"
        },
        {
          "accuracy_class": "(IIII)",
          "max": "2 kg ... 600 t",
          "n_max": 1000,
          "partial_range_ni_max": 1000,
          "max_e1_ratio_max": 5000,
          "tare_balancing_range": "100 % of Max",
          "preset_tare_range": "100 % of Max (1) / 100 % of Max1 (2)",
          "temperature_range": "-30 °C / +40 °C (4)"
        }
      ],
      "description": "n = number of verification scale intervals; ni = number of scale intervals for each partial weighing range; e1 = scale interval of the lowest partial weighing range; Maxr = Max of the largest range for a multiple weighing range instrument.",
      "footnotes": ["1)", "2)", "3)", "4)"]
    }
  ],
  "recommendation": {
    "id": "R76-1",
    "edition": 1992,
    "amendment": "1 (1994)",
    "scheme": "A",
    "accuracy_classes": ["III", "IIII"]
  },
  "test_reports": [
    {
      "id": "1.12-4051368",
      "pages": 13,
      "role": "type_evaluation_report"
    },
    {
      "id": "1.12-4051368/1",
      "pages": 9,
      "role": "test_report"
    }
  ],
  "revision_history": [
    {
      "revision": "1",
      "date": null,
      "changes": null
    }
  ],
  "footnotes": [
    {
      "marker": "1)",
      "text": "this applies to each range of single- and multiple range instruments"
    },
    {
      "marker": "2)",
      "text": "this applies only to multi-interval instruments"
    },
    {
      "marker": "3)",
      "text": "this applies only to multiple range instruments"
    },
    {
      "marker": "4)",
      "text": "in case the load cells are suitable for this temperature range"
    }
  ]
}
